let payload = msg.payload;
try {
    if (Buffer.isBuffer(payload)) payload = payload.toString('utf8');
    if (typeof payload === 'string') payload = JSON.parse(payload);
} catch (err) {
    node.error('JSON de télémétrie invalide: ' + err.message, msg);
    return null;
}
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    node.error('La télémétrie doit être un objet JSON', msg);
    return null;
}
for (const field of ['message_id', 'printer_id', 'ts', 'metrics']) {
    if (payload[field] === undefined || payload[field] === null || payload[field] === '') {
        node.error('Champ obligatoire manquant: ' + field, msg);
        return null;
    }
}
if (typeof payload.metrics !== 'object' || Array.isArray(payload.metrics)) {
    node.error('metrics doit être un objet JSON', msg);
    return null;
}

const metrics = {...payload.metrics};
const state = Number(metrics.printer_state_code);
const demanding = Number(metrics.line_demanding) === 1;
const classification = demanding
    ? (state === 2 ? 'producing' : 'downtime')
    : (state === 2 ? 'idle_jet_on' : 'idle_no_order');

const allRates = global.get('consumption_rates') || {};
const rates = allRates[payload.printer_id] || {};
for (const fluid of ['ink', 'solvent']) {
    const level = Number(metrics[fluid + '_level']);
    const expiry = Number(metrics[fluid + '_days_to_expiry']);
    const previous = rates[fluid];
    let perHour = previous?.perHour || null;
    if (Number.isFinite(level) && previous && payload.ts > previous.ts) {
        if (level > previous.level + 5) {
            perHour = null;
        } else {
            const observed = (previous.level - level) / ((payload.ts - previous.ts) / 3600000);
            if (observed > 0) perHour = perHour ? perHour * 0.75 + observed * 0.25 : observed;
        }
    }
    rates[fluid] = {level, ts: Number(payload.ts), perHour};
    if (perHour > 0) metrics[fluid + '_hours_to_empty'] = level / perHour;
    if (Number.isFinite(expiry)) {
        const depletionDays = perHour > 0 ? level / perHour / 24 : Number.POSITIVE_INFINITY;
        metrics[fluid + '_action_days'] = Math.min(expiry, depletionDays);
        metrics[fluid + '_expiry_limited'] = expiry <= depletionDays ? 1 : 0;
    }
}
allRates[payload.printer_id] = rates;
global.set('consumption_rates', allRates);

const lp = global.get('lineProtocol');
msg.originalPayload = payload;
Object.assign(msg, lp.request(lp.point(
    'printer_telemetry',
    {
        printer_id: payload.printer_id,
        line_id: payload.line_id || 'unknown',
        classification,
    },
    {message_id: payload.message_id, ...metrics},
    payload.ts,
)));
return msg;

if (msg.statusCode !== 204) { node.error('InfluxDB HTTP ' + msg.statusCode + ': ' + (msg.payload || ''), msg); return null; }
const count = Number(global.get('telemetry_messages') || 0) + 1;
global.set('telemetry_messages', count);
node.status({fill:'green', shape:'dot', text:count + ' messages'});
return null;

let payload = msg.payload;
try {
    if (Buffer.isBuffer(payload)) payload = payload.toString('utf8');
    if (typeof payload === 'string') payload = JSON.parse(payload);
} catch (err) {
    node.error('JSON événement invalide: ' + err.message, msg);
    return null;
}
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    node.error('L’événement doit être un objet JSON', msg);
    return null;
}
for (const field of ['message_id', 'printer_id', 'ts', 'event_type']) {
    if (payload[field] === undefined || payload[field] === null || payload[field] === '') {
        node.error('Champ obligatoire manquant: ' + field, msg);
        return null;
    }
}
const tagKeys = new Set(['printer_id','line_id','event_type','code','consumable_type','to_state','demanding','batch_code','part_number']);
const fields = {};
for (const [key, value] of Object.entries(payload)) {
    if (!tagKeys.has(key) && key !== 'ts' && ['string','number','boolean'].includes(typeof value)) fields[key] = value;
}
const lp = global.get('lineProtocol');
msg.originalPayload = payload;
Object.assign(msg, lp.request(lp.point(
    'printer_event',
    {
        printer_id: payload.printer_id,
        line_id: payload.line_id || 'unknown',
        event_type: payload.event_type,
        code: payload.code || 'none',
        consumable_type: payload.consumable_type || 'none',
        to_state: payload.to_state || 'none',
        demanding: payload.demanding === true ? 'true' : 'false',
        batch_code: payload.batch_code || 'none',
        part_number: payload.part_number || 'none',
    },
    fields,
    payload.ts,
)));
return msg;

if (msg.statusCode !== 204) { node.error('InfluxDB HTTP ' + msg.statusCode + ': ' + (msg.payload || ''), msg); return null; }
const count = Number(global.get('event_messages') || 0) + 1;
global.set('event_messages', count);
node.status({fill:'green', shape:'dot', text:count + ' messages'});
return null;

let payload = msg.payload;
try {
    if (Buffer.isBuffer(payload)) payload = payload.toString('utf8');
    if (typeof payload === 'string') payload = JSON.parse(payload);
} catch (err) {
    node.error('JSON marquage invalide: ' + err.message, msg);
    return null;
}
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    node.error('Le marquage doit être un objet JSON', msg);
    return null;
}
for (const field of ['message_id', 'printer_id', 'marked_at', 'dmc']) {
    if (payload[field] === undefined || payload[field] === null || payload[field] === '') {
        node.error('Champ obligatoire manquant: ' + field, msg);
        return null;
    }
}
const lp = global.get('lineProtocol');
msg.originalPayload = payload;
Object.assign(msg, lp.request(lp.point(
    'marking_event',
    {
        printer_id: payload.printer_id,
        line_id: payload.line_id || 'unknown',
        product_ref: payload.product_ref || 'unknown',
        verify_grade: payload.verify_grade || 'unknown',
    },
    {
        message_id: payload.message_id,
        dmc: payload.dmc,
        print_ok: payload.print_ok === true,
        verify_ok: payload.verify_ok === true,
    },
    payload.marked_at,
)));
return msg;

if (msg.statusCode !== 204) { node.error('InfluxDB HTTP ' + msg.statusCode + ': ' + (msg.payload || ''), msg); return null; }
const count = Number(global.get('marking_messages') || 0) + 1;
global.set('marking_messages', count);
node.status({fill:'green', shape:'dot', text:count + ' messages'});
return null;

const healthy = msg.statusCode === 200;
global.set('influx_ready', healthy);
global.set('influx_checked_at', Date.now());
node.status({fill:healthy ? 'green' : 'red', shape:'dot', text:healthy ? 'InfluxDB disponible' : 'InfluxDB indisponible'});
if (!healthy) node.error('InfluxDB HTTP ' + msg.statusCode, msg);
return null;

const checkedAt = Number(global.get('influx_checked_at') || 0);
const ready = global.get('influx_ready') === true && (Date.now() - checkedAt) < 45000;
msg.statusCode = ready ? 200 : 503;
msg.headers = {'content-type':'application/json'};
msg.payload = {
    status: ready ? 'ok' : 'degraded',
    service: 'node-red-ingestion',
    database: ready ? 'ok' : 'unavailable',
    storage: 'InfluxDB 2.x',
    counters: {
        telemetry: Number(global.get('telemetry_messages') || 0),
        events: Number(global.get('event_messages') || 0),
        markings: Number(global.get('marking_messages') || 0)
    }
};
return msg;

if (['prepare_influx_health','influx_health','set_db_healthy'].includes(msg.error?.source?.id)) {
    global.set('influx_ready', false);
    global.set('influx_checked_at', Date.now());
}
const failedPayload = msg.originalPayload || msg.payload;
const originalTopic = msg.topic || null;
msg.topic = 'sgx/system/dead-letter';
msg.payload = JSON.stringify({
    failed_at: new Date().toISOString(),
    error: msg.error?.message || 'unknown ingestion error',
    source_node: msg.error?.source?.name || msg.error?.source?.id || 'unknown',
    original_topic: originalTopic,
    payload: failedPayload
});
return msg;
